#include <stdio.h>

/* 把外面那张牌往后挪 count 只碗 */
void step(int **pp, int count) {
    for (int i = 0; i < count; i++) {
        *pp = *pp + 1;
    }
}

int main(void) {
    int bowls[5] = {{row}};
    int *p = &bowls[0];

    step(&p, {count});
    printf("牌子现在指着：%d\n", *p);
    return 0;
}
